package com.hospital.doctor.service;

import com.hospital.doctor.dto.DoctorRequestDto;
import com.hospital.doctor.model.Doctor;
import com.hospital.doctor.repository.DoctorRepository;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.InjectMocks;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;

import java.util.Optional;
import java.util.Set;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.mockito.Mockito.times;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

@ExtendWith(MockitoExtension.class)
class DoctorServiceTest {

    @Mock
    private DoctorRepository doctorRepository;

    @InjectMocks
    private DoctorService doctorService;

    private DoctorRequestDto validRequest() {
        DoctorRequestDto request = new DoctorRequestDto();
        request.setFirstName("An");
        request.setLastName("Nguyen");
        request.setEmail("new.email@example.com");
        request.setPhone("0123456789");
        request.setLicenseNumber("LIC-NEW-01");
        request.setSpecialization("Cardiology");
        request.setQualification("MD");
        request.setExperienceYears(10);
        request.setConsultationFee(100.0);
        request.setDepartment("Cardiology");
        request.setRoomNumber("R-101");
        request.setAvailableDays(Set.of("Monday"));
        request.setStartTime("09:00");
        request.setEndTime("17:00");
        request.setIsAvailable(true);
        return request;
    }

    private Doctor activeDoctor() {
        Doctor doctor = new Doctor();
        doctor.setId(101L);
        doctor.setFirstName("An");
        doctor.setLastName("Nguyen");
        doctor.setEmail("old.email@example.com");
        doctor.setPhone("0123456789");
        doctor.setLicenseNumber("LIC-OLD-01");
        doctor.setSpecialization("Cardiology");
        return doctor;
    }

    @Test
    // GreyTest trace: updateDoctor | email trùng bác sĩ khác, thuộc bác sĩ hiện tại hoặc không tìm thấy | BR-072 -> TP-059 -> TC-1779
    void updateDoctor_emailConflictAndNonConflictCases() {
        // Arrange
        DoctorRequestDto request = validRequest();
        Doctor activeForConflict = activeDoctor();
        Doctor otherDoctor = new Doctor();
        otherDoctor.setId(202L);
        when(doctorRepository.findActiveById(101L)).thenReturn(Optional.of(activeForConflict));
        when(doctorRepository.findByEmail("new.email@example.com")).thenReturn(Optional.of(otherDoctor));

        // Act
        IllegalArgumentException exception = assertThrows(
                IllegalArgumentException.class,
                () -> doctorService.updateDoctor(101L, request));

        // Assert
        assertEquals("Doctor with email new.email@example.com already exists", exception.getMessage());
        verify(doctorRepository).findActiveById(101L);
        verify(doctorRepository).findByEmail("new.email@example.com");
        verify(doctorRepository, times(0)).findByLicenseNumber("LIC-NEW-01");
        verify(doctorRepository, times(0)).save(org.mockito.ArgumentMatchers.any(Doctor.class));

        // Arrange and Act: email của bác sĩ hiện tại.
        Doctor activeForOwnEmail = activeDoctor();
        when(doctorRepository.findActiveById(101L)).thenReturn(Optional.of(activeForOwnEmail));
        when(doctorRepository.findByEmail("new.email@example.com")).thenReturn(Optional.of(activeForOwnEmail));
        when(doctorRepository.findByLicenseNumber("LIC-NEW-01")).thenReturn(Optional.empty());
        when(doctorRepository.save(org.mockito.ArgumentMatchers.any(Doctor.class)))
                .thenAnswer(invocation -> invocation.getArgument(0));
        Doctor ownEmailResult = doctorService.updateDoctor(101L, request);

        // Assert
        assertEquals(101L, ownEmailResult.getId());
        assertEquals("new.email@example.com", ownEmailResult.getEmail());

        // Arrange and Act: email không tìm thấy.
        Doctor activeForMissingEmail = activeDoctor();
        when(doctorRepository.findActiveById(101L)).thenReturn(Optional.of(activeForMissingEmail));
        when(doctorRepository.findByEmail("new.email@example.com")).thenReturn(Optional.empty());
        when(doctorRepository.findByLicenseNumber("LIC-NEW-01")).thenReturn(Optional.empty());
        Doctor missingEmailResult = doctorService.updateDoctor(101L, request);

        // Assert
        assertEquals(101L, missingEmailResult.getId());
        assertEquals("new.email@example.com", missingEmailResult.getEmail());
        verify(doctorRepository, times(3)).findActiveById(101L);
        verify(doctorRepository, times(3)).findByEmail("new.email@example.com");
        verify(doctorRepository, times(2)).findByLicenseNumber("LIC-NEW-01");
        verify(doctorRepository, times(2)).save(org.mockito.ArgumentMatchers.any(Doctor.class));
    }
}
